									  break;
        case EVENT_INCOMING_TLSDS_TRANSFER:
            eventReader = new IncomingSDSTLTransferEventReader(*this);
            break;

        case EVENT_INCOMING_TLSDS_REPORT:
            eventReader = new IncomingSDSTLReportEventReader(*this);
