        //case EVENT_ALARM:
        //    eventReader = new AlarmEventEventReader(*this);
        //    break;

        //case EVENT_GET_NE:
        //    eventReader = new GetNeEventReader(*this);
        //    break;

        //case EVENT_GET_TSU_ACTIVE_ALARM:
        //    eventReader = new GetTsuActiveAlarmListEventReader(*this);
        //    break;

        //case EVENT_GET_SC_ACTIVE_ALARM:
        //    eventReader = new GetSCActiveAlarmListEventReader(*this);
        //    break;

        //case EVENT_GET_TIU_ACTIVE_ALARM:
